window.kbPageData["views/entry/k-5e448b96b003ad3a"] = {"key":"entry/k-5e448b96b003ad3a","state":{"route":"entry/k-5e448b96b003ad3a"},"node":{"id":"k-5e448b96b003ad3a","mode":"k","title":"政治领导力、思想引领力、群众组织力、社会号召力","type":"概念与词义","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["非时政"]},"directorySummary":"3.政治领导力、思想引领力、群众组织力、社会号召力\n（1）党的政治领导力：政治领导力是马克思主义政党第一位的能力，主要体现为对\n党的路线方针政策等重大决策的领导，对国家发展道路、发展阶段、发展布局、国际形势\n等重大判断的领导，对捍卫政治立场、把准政治方向、坚持政治原则以及保持政治定力、\n防范政治风险…","sources":[{"id":"84c20e60e45d939e","label":"政治领导力、思想引领力、群众组织力、社会号召力","topic":"党政制度与理论","category":"非时政","text":"3.政治领导力、思想引领力、群众组织力、社会号召力\n（1）党的政治领导力：政治领导力是马克思主义政党第一位的能力，主要体现为对\n党的路线方针政策等重大决策的领导，对国家发展道路、发展阶段、发展布局、国际形势\n等重大判断的领导，对捍卫政治立场、把准政治方向、坚持政治原则以及保持政治定力、\n防范政治风险等方面的领导。\n（2）党的思想引领力：是保证全党全国各族人民思想统一、步调一致的坚实基础，\n主要体现为坚持马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科\n学发展观，全面贯彻习近平新时代中国特色社会主义思想，深入学习贯彻习近平党建思\n想；坚持马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，不断\n开辟马克思主义中国化时代化新境界；坚持用党的创新理论武装全党、教育人民，用马克\n思主义中国化时代化的最新成果引领社会向前发展。\n（3）党的群众组织力：是我们党坚如磐石、坚不可摧的力量根基。主要体现在两个\n方面，一是坚持党的群众路线，一切为了群众、一切依靠群众，从群众中来、到群众中去，\n坚信人民群众是历史的创造者，相信人民群众中蕴藏着无穷的智慧和力量，切实解决人民\n群众急难愁盼问题，不断增强人民群众的获得感、幸福感、安全感。二是党的各级组织和\n党员个人以身作则、率先垂范，处处走在群众的前面，用自身的言行为群众立标杆、作示\n范，以自身的先进性吸引群众、组织群众，巩固深厚的群众基础。\n（4）党的社会号召力：是党的先进性和感召力的重要体现。主要体现为党通过美好\n的愿景来鼓舞社会，以科学的战略安排来引导社会，以健全的组织来动员社会，以可触可\n感的成就来吸引社会，以廉洁亲民的形象来感染社会。\n——中国共产党新闻网","source":{"doc":"41195a191a57c1c36332","first":11,"last":12,"page":11,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-5e448b96b003ad3a":[]}};
